const copyButton=document.querySelector(".copy-email");if(copyButton&&navigator.clipboard&&window.isSecureContext){copyButton.hidden=!1;let e;copyButton.addEventListener("click",async()=>{const t=document.querySelector(".copy-status");clearTimeout(e);try{await navigator.clipboard.writeText(copyButton.dataset.email),t.textContent=copyButton.dataset.copied}catch{t.textContent=copyButton.dataset.failed}e=setTimeout(()=>{t.textContent=""},4e3)})}document.querySelectorAll(".language-switch a").forEach(e=>{e.addEventListener("click",()=>{if(location.hash&&document.querySelector(".hero")){const t=new URL(e.href);t.hash=location.hash,e.href=t.href}})})